<?php require_once __DIR__.'/app.php'; require_login(); require_once __DIR__.'/ui.php'; ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Novo proprietário · Central Imóveis</title><link rel="stylesheet" href="css/style.css"></head><body><main class="container pequeno"><a class="voltar" href="proprietarios.php">← Voltar aos proprietários</a><?php render_nav('proprietarios'); ?><header class="page-head"><div><span class="eyebrow">PROPRIETÁRIO</span><h1>Novo proprietário</h1><p class="subtitulo">Cadastre os dados uma única vez para reutilizar em vários imóveis e contratos.</p></div></header><?php if($m=flash('error')):?><div class="alerta erro"><?=e($m)?></div><?php endif;?><form action="salvar_proprietario.php" method="POST" class="formulario"><?=csrf_field()?>
<section class="form-card"><div class="form-card-title"><span>01</span><div><strong>Identificação</strong><small>Dados que serão reutilizados no contrato.</small></div></div><div class="grid"><label>Tipo<select name="tipo" id="tipo"><option value="pf">Pessoa física</option><option value="pj">Pessoa jurídica</option></select></label><label>Nome / razão social<input name="nome" required maxlength="180"></label><label>CPF<input name="cpf" maxlength="14"></label><label>Profissão<input name="profissao" maxlength="120"></label><label>Gênero<select name="genero"><option value="">Não informado</option><option>Feminino</option><option>Masculino</option><option>Outro</option></select></label><label>Estado civil<select name="estado_civil"><option value="">Não informado</option><option>solteiro(a)</option><option>casado(a)</option><option>divorciado(a)</option><option>viúvo(a)</option><option>união estável</option></select></label><label>RG<input name="rg" maxlength="40"></label><label>CNPJ<input name="cnpj" maxlength="30"></label><label>Representante legal<input name="representante_legal" maxlength="180"></label><label>RG do representante<input name="rg_representante" maxlength="40"></label><label>Telefone<input name="telefone" maxlength="40"></label><label>E-mail<input name="email" type="email" maxlength="180"></label></div></section>
<section class="form-card"><div class="form-card-title"><span>02</span><div><strong>Endereço</strong><small>Também usado para preencher o contrato.</small></div></div><div class="grid"><label>CEP<input id="cep" name="cep" maxlength="9"></label><label>Rua / logradouro<input id="endereco" name="endereco" maxlength="250"></label><label>Número<input name="numero" maxlength="30"></label><label>Complemento<input name="complemento" maxlength="120"></label><label>Bairro<input id="bairro" name="bairro" maxlength="100"></label><label>Cidade<input id="cidade" name="cidade" maxlength="100" value="São Sebastião"></label><label>UF<input id="uf" name="uf" maxlength="2" value="SP"></label></div></section>
<section class="form-card"><div class="form-card-title"><span>03</span><div><strong>Pagamento do proprietário</strong><small>Opcional; fica disponível para o gerador de contrato.</small></div></div><div class="grid"><label>Banco<input name="banco_codigo" maxlength="20"></label><label>Agência<input name="banco_agencia" maxlength="30"></label><label>Tipo de conta<input name="tipo_conta" maxlength="30" placeholder="CC (Corrente)"></label><label>Conta<input name="banco_conta" maxlength="40"></label><label>PIX<input name="pix" maxlength="180"></label></div></section>
<div class="form-bottom"><a class="botao secundario" href="proprietarios.php">Cancelar</a><button class="botao" type="submit">Salvar proprietário</button></div></form><?php render_footer();?></main><script>const cep=document.getElementById('cep');cep.addEventListener('blur',async()=>{const v=cep.value.replace(/\D/g,'');if(v.length!==8)return;try{const r=await fetch('https://viacep.com.br/ws/'+v+'/json/');const d=await r.json();if(d.erro)return;document.getElementById('endereco').value=d.logradouro||'';document.getElementById('bairro').value=d.bairro||'';document.getElementById('cidade').value=d.localidade||'';document.getElementById('uf').value=d.uf||'';}catch(e){}});</script></body></html>